            op = tokens[pos][0]
            pos += 1
            right = parse_unary()
            if op == '*':
                left = left * right
            else:
                left = int(left / right)
        return left

    def parse_unary():
        nonlocal pos
        if pos < len(tokens) and tokens[pos][0] == '-':
            pos += 1
            return -parse_unary()
        elif pos < len(tokens) and tokens[pos][0] == '+':
            pos += 1
            return parse_unary()
        else:
            return parse_primary()

